const crypto = require('crypto');
const secret = $env.N8N_WEBHOOK_SECRET;
if (!secret) { throw new Error('N8N_WEBHOOK_SECRET is not set'); }
const item = $input.first();
const headers = (item.json && item.json.headers) || {};
const ts = headers['x-lit-timestamp'];
const eventId = headers['x-lit-event-id'];
const signature = headers['x-lit-signature'];
if (!ts || !eventId || !signature) { throw new Error('Missing signing headers'); }
const body = (item.json && item.json.body) !== undefined ? item.json.body : {};
const rawBody = typeof body === 'string' ? body : JSON.stringify(body);
const mac = crypto.createHmac('sha256', secret).update(ts + '.' + eventId + '.' + rawBody).digest('hex');
const expected = 'v1=' + mac;
const a = Buffer.from(expected);
const b = Buffer.from(String(signature));
const matches = a.length === b.length && crypto.timingSafeEqual(a, b);
if (!matches) { throw new Error('Signature verification failed'); }
const nowSec = Math.floor(Date.now() / 1000);
if (Math.abs(nowSec - Number(ts)) > 300) { throw new Error('Signature timestamp outside tolerance'); }
return [{ json: { verified: true, eventId, timestamp: ts, body } }];

const item = $input.first().json;
const payload = (item.body && item.body.payload) ? item.body.payload : (item.body || {});

const clientId = String(payload.clientId || payload.client_id || 'anonymous').trim();
const clientName = String(payload.clientName || payload.name || 'Valued Client').trim();
const clientEmail = String(payload.email || payload.clientEmail || '').trim().toLowerCase();
const projectId = String(payload.projectId || payload.project_id || '').trim();
const ticketId = String(payload.ticketId || payload.ticket_id || '').trim();
const rawRating = Number(payload.rating || payload.score || 10);
const rating = Math.max(1, Math.min(10, rawRating));
const feedbackText = String(payload.feedback || payload.comments || '').trim();
const category = String(payload.category || 'project_delivery').trim();

const lowerText = feedbackText.toLowerCase();
const positiveWords = ['great', 'excellent', 'fast', 'smooth', 'loved', 'perfect', 'awesome', 'recommend', 'clean', 'high quality', 'exceptional'];
const negativeWords = ['slow', 'buggy', 'disappointed', 'delay', 'issue', 'frustrated', 'poor', 'unhappy', 'bad', 'broken', 'error'];

let posCount = 0;
for (const w of positiveWords) {
  if (lowerText.includes(w)) posCount++;
}
let negCount = 0;
for (const w of negativeWords) {
  if (lowerText.includes(w)) negCount++;
}

let sentiment = 'neutral';
if (rating >= 8 || posCount > negCount) {
  sentiment = 'positive';
} else if (rating <= 5 || negCount > posCount) {
  sentiment = 'negative';
}

const isPromoter = rating >= 9;
const isDetractor = rating <= 6;

return [{
  json: {
    eventId: item.eventId,
    verified: item.verified,
    clientId,
    clientName,
    clientEmail,
    projectId,
    ticketId,
    rating,
    feedbackText,
    category,
    sentiment,
    isPromoter,
    isDetractor,
    processedAt: new Date().toISOString()
  }
}];

const item = $input.first().json;
const testimonialInvitation = {
  recipientName: item.clientName,
  recipientEmail: item.clientEmail,
  rating: item.rating,
  sentiment: item.sentiment,
  invitationSubject: `Thank you for your ${item.rating}/10 review of Logic Intelligence Technologies`,
  testimonialPortalPath: `/client/testimonials?client_id=${item.clientId}&project_id=${item.projectId}`,
  advocateTier: item.rating === 10 ? 'VIP_ADVOCATE' : 'STANDARD_ADVOCATE',
  referralIncentiveEligible: true
};

return [{
  json: {
    eventId: item.eventId,
    status: 'promoter_testimonial_dispatched',
    detail: {
      clientId: item.clientId,
      projectId: item.projectId,
      rating: item.rating,
      testimonialInvitation,
      recordedAt: new Date().toISOString()
    }
  }
}];

const item = $input.first().json;
const isDetractor = item.isDetractor;

const recoveryCard = {
  severity: isDetractor ? 'P1_ELEVATED' : 'P3_ROUTINE',
  clientName: item.clientName,
  clientEmail: item.clientEmail,
  rating: item.rating,
  feedback: item.feedbackText || 'No comments provided',
  actionRequired: isDetractor
    ? 'Lead Engineer direct outreach within 24 hours to resolve friction points'
    : 'Log neutral feedback in CRM for retrospective review',
  escalatedTo: isDetractor ? 'Vikash Saravanan (Lead System Engineer)' : 'Operations Support'
};

return [{
  json: {
    eventId: item.eventId,
    status: isDetractor ? 'service_recovery_escalated' : 'feedback_logged',
    detail: {
      clientId: item.clientId,
      projectId: item.projectId,
      rating: item.rating,
      recoveryCard,
      recordedAt: new Date().toISOString()
    }
  }
}];

const crypto = require('crypto');
const secret = $env.N8N_WEBHOOK_SECRET;
if (!secret) { throw new Error('N8N_WEBHOOK_SECRET is not set'); }
const item = $input.first();
const eventId = item.json.eventId;
const ts = String(Math.floor(Date.now() / 1000));
const payload = {
  eventId,
  status: item.json.status || 'processed',
  detail: item.json.detail || {}
};
const rawBody = JSON.stringify(payload);
const mac = crypto.createHmac('sha256', secret).update(ts + '.' + eventId + '.' + rawBody).digest('hex');
return [{ json: { eventId, status: payload.status, rawBody, timestamp: ts, signature: 'v1=' + mac } }];
